SELECT
	cl.Codigo,
	Razao_Social,
	Bloqueado = case
				when Bloqueado = 1 then 'SIM'
				when Bloqueado = 0 then 'NÃO'
				end, 
	Motivo_Bloqueio,
	Cgc_Cpf,
	Cod_RamoAtividade,
	RM.Descricao,
	Tip_Clien = case
					when Pessoa = 'J' then 'Pessoa Juridica'
					when Pessoa = 'F' then 'Pessoa Física'
				end
FROM CLIEN CL
	LEFT JOIN RMATV RM on CL.Cod_RamoAtividade = RM.Codigo
WHERE 
	Cgc_Cpf in ('01778108000172',
